import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation in Python. This data structure allows for efficient 
    membership testing of items with a possibility of false positives. The optimal 
    size of the bit array and the number of hash functions are calculated based 
    on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal size of bit array (m)
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        # Calculate optimal number of hash functions (k)
        self.hash_count = self._optimal_number_of_hash_functions(self.size, expected_items)

        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculates the optimal size of the bit array."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_number_of_hash_functions(self, m: int, n: int) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, int(m / n * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generates hash values for the given item based on the number of hash functions."""
        hash_values = []
        for i in range(self.hash_count):
            hash_result = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            hash_index = int(hash_result, 16) % self.size
            hash_values.append(hash_index)
        return hash_values

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Checks whether an item is in the Bloom Filter."""
        for index in self._hashes(item):
            if self.bit_array[index] == 0:
                return False
        return True

