    and hash index calculation. This implementation derives the optimal parameters based 
    on the expected number of items and desired false positive rate while using built-in
    hashing for uniqueness.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self._calculate_hash_functions(self.size, expected_items)

        self.bit_array = 0  # Using an integer to represent the bit array

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculates the size of the bit array using the formula derived from the false positive rate."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _calculate_hash_functions(self, m: int, n: int) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, round(m / n * math.log(2)))

    def _get_hash_indices(self, item: str) -> list:
        """Generates hash indices for the item based on the number of hash functions."""
        indices = []
        item_bytes = item.encode()
        for i in range(self.hash_count):
            hash_value = hashlib.sha256(item_bytes + i.to_bytes(4, byteorder='big')).hexdigest()
            index = int(hash_value, 16) % self.size
            indices.append(index)
        return indices

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter."""
        for index in self._get_hash_indices(item):
            self.bit_array |= (1 << index)

    def contains(self, item: str) -> bool:
        """Checks whether an item is in the Bloom Filter."""
        for index in self._get_hash_indices(item):
            if not (self.bit_array & (1 << index)):
                return False
        return True

